begin; create extension if not exists pgtap with schema extensions; set search_path=public,extensions; select plan(18);
select has_table('public','commercial_proposal_creation_requests','idempotency registry exists');
select has_function('public','create_server_derived_patrimonial_proposal_transaction',array['uuid','uuid','uuid','uuid','uuid','text','text','jsonb','jsonb','jsonb','text'],'internal transaction exists');
select ok(not has_function_privilege('anon','public.create_server_derived_patrimonial_proposal_transaction(uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb,jsonb,text)','EXECUTE'),'anon cannot execute');
select ok(not has_function_privilege('authenticated','public.create_server_derived_patrimonial_proposal_transaction(uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb,jsonb,text)','EXECUTE'),'authenticated cannot execute');
select ok(has_function_privilege('service_role','public.create_server_derived_patrimonial_proposal_transaction(uuid,uuid,uuid,uuid,uuid,text,text,jsonb,jsonb,jsonb,text)','EXECUTE'),'service role can execute');
insert into public.organizations(id,name,slug) values('f1000000-0000-4000-8000-000000000001','C31 Org','c31-org');
insert into auth.users(id) values('f2000000-0000-4000-8000-000000000001');
insert into public.profiles(id,organization_id,name,email,role) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','Master','master@c31.test','master');
insert into public.crm_leads(id,organization_id,nome) values('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','Lead C31');
create function pg_temp.snap(p_sim text) returns jsonb language sql as $$select jsonb_build_object('schemaVersion','commercial-proposal/v1','proposalKind','patrimonial_strategy','provenance',jsonb_build_object('authority','server_derived','simulationId',p_sim,'calculationEngineKey','engine:reference-capital-exclusive-2227','calculationEngineVersion','1.0.0','financialProductKey','reference_capital_exclusive_2227','financialProductVersion','2227-v1'),'product','{}'::jsonb,'strategy',jsonb_build_object('quotaCount',2,'totalCredit',jsonb_build_object('amountCents',40000000,'currency','BRL')),'composition','[{},{}]'::jsonb,'commercialTerms','{}'::jsonb,'disclosures','[]'::jsonb)$$;
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($$select public.create_server_derived_patrimonial_proposal_transaction('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','request-0001',repeat('a',64),'{}','{}',pg_temp.snap('f4000000-0000-4000-8000-000000000001'),public.commercial_proposal_terms_hash(pg_temp.snap('f4000000-0000-4000-8000-000000000001')))$$,'42501','CP_INTERNAL_BOUNDARY_REQUIRED','authenticated direct call is denied');
select set_config('request.jwt.claim.role','service_role',true);
select lives_ok($$select public.create_server_derived_patrimonial_proposal_transaction('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','f5000000-0000-4000-8000-000000000001','request-0001',repeat('a',64),'{"intent":true}','{"result":true}',pg_temp.snap('f4000000-0000-4000-8000-000000000001'),public.commercial_proposal_terms_hash(pg_temp.snap('f4000000-0000-4000-8000-000000000001')))$$,'atomic creation succeeds');
select is((select snapshot_authority from public.crm_lead_commercial_proposals where id='f5000000-0000-4000-8000-000000000001'),'server_derived','authority is fixed internally');
select is((select commercial_terms_hash from public.crm_lead_commercial_proposals where id='f5000000-0000-4000-8000-000000000001'),public.commercial_proposal_terms_hash(pg_temp.snap('f4000000-0000-4000-8000-000000000001')),'database verifies hash');
select is((select simulation_id from public.crm_lead_commercial_proposals where id='f5000000-0000-4000-8000-000000000001'),'f4000000-0000-4000-8000-000000000001'::uuid,'proposal links authoritative simulation');
select is((select count(*)::integer from public.commercial_proposal_audit_events where proposal_id='f5000000-0000-4000-8000-000000000001' and event_type='server_derived_proposal_created'),1,'audit is recorded');
select is((select (public.create_server_derived_patrimonial_proposal_transaction('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000002','f5000000-0000-4000-8000-000000000002','request-0001',repeat('a',64),'{}','{}',pg_temp.snap('f4000000-0000-4000-8000-000000000002'),public.commercial_proposal_terms_hash(pg_temp.snap('f4000000-0000-4000-8000-000000000002')))->>'outcome')),'already_created','retry is idempotent');
select is((select count(*)::integer from public.crm_lead_simulations where organization_id='f1000000-0000-4000-8000-000000000001'),1,'retry does not duplicate simulation');
select throws_ok($$select public.create_server_derived_patrimonial_proposal_transaction('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000003','f5000000-0000-4000-8000-000000000003','request-0001',repeat('b',64),'{}','{}',pg_temp.snap('f4000000-0000-4000-8000-000000000003'),public.commercial_proposal_terms_hash(pg_temp.snap('f4000000-0000-4000-8000-000000000003')))$$,'P0001','CP_IDEMPOTENCY_CONFLICT','changed intent conflicts');
select throws_ok($$select public.create_server_derived_patrimonial_proposal_transaction('f1000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000004','f5000000-0000-4000-8000-000000000004','request-0004',repeat('c',64),'{}','{}',pg_temp.snap('f4000000-0000-4000-8000-000000000004'),repeat('0',64))$$,'P0001','CP_SNAPSHOT_HASH_MISMATCH','tampered hash rolls back');
select is((select count(*)::integer from public.crm_lead_simulations where id='f4000000-0000-4000-8000-000000000004'),0,'failed proposal leaves no simulation');
select is((select count(*)::integer from public.commercial_proposal_creation_requests where organization_id='f1000000-0000-4000-8000-000000000001'),1,'idempotency registry is consistent');
select set_config('request.jwt.claim.role','authenticated',true); select set_config('request.jwt.claim.sub','f2000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.approve_commercial_proposal_transaction('f5000000-0000-4000-8000-000000000001')$$,'server-derived proposal remains compatible with C2 approval');
select * from finish(); rollback;
